{
  "appearance_facts": [
    {
      "location": "Chart area",
      "fact": "A single continuous orange line connects data points for each year from 2012 to 2023."
    },
    {
      "location": "2012 to 2015",
      "fact": "The line begins at a low position, rises slightly, peaks at 2014, and then drops to a local minimum at 2015."
    },
    {
      "location": "2015 to 2018",
      "fact": "The line shows a steady upward trajectory, rising from the 2015 low to a peak at 2018."
    },
    {
      "location": "2018 to 2020",
      "fact": "The line remains relatively flat, with a very slight decline or plateau between the 2018 peak and the 2020 point."
    },
    {
      "location": "2020 to 2022",
      "fact": "The line exhibits a steep, sharp increase, reaching its highest vertical position on the chart at 2022."
    },
    {
      "location": "2022 to 2023",
      "fact": "The line descends from the 2022 peak to the 2023 point, though the 2023 point remains significantly higher than the starting points in 2012-2015."
    },
    {
      "location": "Overall trend",
      "fact": "The general direction of the line is upward from the left side of the chart (2012) to the right side (2023), ending at a much higher vertical level than it began."
    }
  ],
  "printed_facts": [
    {
      "location": "Top of image",
      "fact": "The main title reads 'Reduced Screening Referrals Across Hospitals from 2012 to 2023'."
    },
    {
      "location": "Below title",
      "fact": "A subtitle reads 'Referral-monitoring record shown in the dashboard summary'."
    },
    {
      "location": "Y-axis",
      "fact": "The vertical axis is labeled 'Screening referrals' with tick marks at 0, 800, 1600, 2400, and 3200."
    },
    {
      "location": "X-axis",
      "fact": "The horizontal axis is labeled 'Year' with tick marks for every year from 2012 to 2023."
    }
  ],
  "public_definitions": [
    "Route to growth-focused referral follow-up",
    "Route to reduction-focused referral follow-up",
    "Route to standard referral monitoring"
  ],
  "uncertain": [
    "The chart title explicitly states 'Reduced Screening Referrals', which conflicts with the visual data showing an overall increase in the number of referrals over the period.",
    "It is unclear whether the 'growth' or 'reduction' in the options refers to the visual trend of the line or the semantic meaning of the title."
  ]
}
